/*
 * Midnight network backend: Lace wallet (DApp Connector API v4) + Midnight.js 4.1.
 * Proofs are generated by the proof server configured in Lace; transactions are
 * balanced (tDUST fees) and submitted by Lace. Pattern follows midnightntwrk/example-bboard.
 */
import semver from 'semver';
import type { ConnectedAPI, InitialAPI } from '@midnight-ntwrk/dapp-connector-api';
import { deployContract, findDeployedContract } from '@midnight-ntwrk/midnight-js-contracts';
import { FetchZkConfigProvider } from '@midnight-ntwrk/midnight-js-fetch-zk-config-provider';
import { httpClientProofProvider } from '@midnight-ntwrk/midnight-js-http-client-proof-provider';
import { indexerPublicDataProvider } from '@midnight-ntwrk/midnight-js-indexer-public-data-provider';
import { setNetworkId } from '@midnight-ntwrk/midnight-js-network-id';
import { CompiledContract } from '@midnight-ntwrk/midnight-js-protocol/compact-js';
import { Transaction, type FinalizedTransaction } from '@midnight-ntwrk/midnight-js-protocol/ledger';
import { fromHex, toHex } from '@midnight-ntwrk/midnight-js-protocol/compact-runtime';
import { Contract, ledger, pureCircuits, witnesses, type ZkRemitPrivateState } from '@zk-remit/contract';
import { browserPrivateStateProvider } from './privateStateProvider';
import { type Backend, snapshot } from './types';

export const NETWORK_ID = (import.meta.env.VITE_NETWORK_ID as string) || 'preview';
const PSID = 'zkRemitPrivateState';

const compiled: any = (CompiledContract as any)
  .make('ZkRemit', Contract)
  .pipe((CompiledContract as any).withWitnesses(witnesses), (CompiledContract as any).withCompiledFileAssets('./managed/zk-remit'));

export type WalletInfo = { name: string; apiVersion: string; shieldedAddress: string; api: ConnectedAPI };

export const detectLace = (): InitialAPI | undefined => {
  const m = (window as any).midnight as Record<string, InitialAPI> | undefined;
  if (!m) return undefined;
  return Object.values(m).find((w) => !!w && typeof w === 'object' && 'apiVersion' in w && semver.satisfies(w.apiVersion, '4.x'));
};

export const connectLace = async (): Promise<WalletInfo> => {
  let initial: InitialAPI | undefined;
  for (let i = 0; i < 30 && !initial; i++) {
    initial = detectLace();
    if (!initial) await new Promise((r) => setTimeout(r, 100));
  }
  if (!initial) throw new Error('Midnight Lace wallet (DApp Connector v4) not found. Install Lace and enable Midnight.');
  setNetworkId(NETWORK_ID as any);
  const api = await initial.connect(NETWORK_ID);
  const addrs = await api.getShieldedAddresses();
  return { name: (initial as any).name ?? 'Lace', apiVersion: initial.apiVersion, shieldedAddress: addrs.shieldedAddress, api };
};

const makeProviders = async (api: ConnectedAPI) => {
  const cfg = await api.getConfiguration();
  const shielded = await api.getShieldedAddresses();
  const base = new URL(import.meta.env.BASE_URL, window.location.origin).toString().replace(/\/$/, '');
  const zkConfigProvider = new FetchZkConfigProvider<any>(base, fetch.bind(window));
  return {
    privateStateProvider: browserPrivateStateProvider<typeof PSID, ZkRemitPrivateState>(),
    zkConfigProvider,
    proofProvider: httpClientProofProvider(cfg.proverServerUri!, zkConfigProvider),
    publicDataProvider: indexerPublicDataProvider(cfg.indexerUri, cfg.indexerWsUri),
    walletProvider: {
      getCoinPublicKey: () => shielded.shieldedCoinPublicKey,
      getEncryptionPublicKey: () => shielded.shieldedEncryptionPublicKey,
      balanceTx: async (tx: any): Promise<FinalizedTransaction> => {
        const res = await api.balanceUnsealedTransaction(toHex(tx.serialize()));
        return (Transaction as any).deserialize('signature', 'proof', 'binding', fromHex(res.tx));
      },
    },
    midnightProvider: {
      submitTx: async (tx: FinalizedTransaction) => {
        await api.submitTransaction(toHex(tx.serialize()));
        return tx.identifiers()[0];
      },
    },
  } as any;
};

export class MidnightBackend implements Backend {
  readonly kind = 'midnight' as const;
  readonly label: string;
  private constructor(private providers: any, private deployed: any, readonly contractAddress: string) {
    this.label = `Midnight ${NETWORK_ID} · ${contractAddress.slice(0, 10)}…`;
  }

  static async deploy(api: ConnectedAPI, issuerSecret: Uint8Array): Promise<MidnightBackend> {
    const providers = await makeProviders(api);
    const deployed = await deployContract(providers, {
      compiledContract: compiled,
      privateStateId: PSID,
      initialPrivateState: { issuerSecret },
      args: [pureCircuits.issuerPublicKey(issuerSecret)],
    } as any);
    const addr = (deployed as any).deployTxData.public.contractAddress as string;
    return new MidnightBackend(providers, deployed, addr);
  }

  static async join(api: ConnectedAPI, contractAddress: string, ps: ZkRemitPrivateState): Promise<MidnightBackend> {
    const providers = await makeProviders(api);
    providers.privateStateProvider.setContractAddress(contractAddress);
    const deployed = await findDeployedContract(providers, {
      contractAddress,
      compiledContract: compiled,
      privateStateId: PSID,
      initialPrivateState: ps,
    } as any);
    return new MidnightBackend(providers, deployed, contractAddress);
  }

  private async as(ps: ZkRemitPrivateState) {
    this.providers.privateStateProvider.setContractAddress(this.contractAddress);
    await this.providers.privateStateProvider.set(PSID, ps);
  }
  private tx = (r: any) => ({ txHash: r?.public?.txHash as string | undefined });

  async issueCredential(ps: ZkRemitPrivateState, c: Uint8Array) { await this.as(ps); await this.deployed.callTx.issueCredential(c); }
  async openCorridor(ps: ZkRemitPrivateState, f: bigint, t: bigint) { await this.as(ps); await this.deployed.callTx.openCorridor(f, t); }
  async advanceEpoch(ps: ZkRemitPrivateState) { await this.as(ps); await this.deployed.callTx.advanceEpoch(); }
  async sendRemittance(ps: ZkRemitPrivateState, to: bigint, a: bigint, s: Uint8Array, slot: bigint, tag: Uint8Array) {
    await this.as(ps);
    return this.tx(await this.deployed.callTx.sendRemittance(to, a, s, slot, tag));
  }
  async claim(ps: ZkRemitPrivateState, id: Uint8Array, a: bigint, s: Uint8Array) {
    await this.as(ps);
    return this.tx(await this.deployed.callTx.claim(id, a, s));
  }
  async proveReceiptOwnership(ps: ZkRemitPrivateState, id: Uint8Array, ch: Uint8Array) {
    await this.as(ps);
    return this.tx(await this.deployed.callTx.proveReceiptOwnership(id, ch));
  }
  async ledger() {
    const st = await this.providers.publicDataProvider.queryContractState(this.contractAddress);
    if (!st) throw new Error('Contract state not found on indexer');
    return snapshot(ledger(st.data));
  }
}
